#include <iostream>
#include <vector>

std::vector<int> DedupePreserveOrder(const std::vector<int>& values);

int main()
{
    int n;
    while (std::cin >> n)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        std::vector<int> result = DedupePreserveOrder(values);
        for (size_t i = 0; i < result.size(); i++)
        {
            std::cout << result[i] << (i + 1 < result.size() ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}
